[assistant] """
missing_skill — build missing skill
"""


def propose(ctx: dict) -> dict:
    """Analyse the context and propose a plan for building the missing skill."""
    skill_id = ctx.get("skill_id", "unknown")
    goal = ctx.get("goal", "build missing skill")
    constraints = ctx.get("constraints", [])

    plan_steps = [
        f"Identify requirements for skill '{skill_id}'",
        "Scaffold propose / apply / test entrypoints",
        "Validate against constraints",
        "Run isolated self-test",
    ]

    return {
        "ok": True,
        "skill_id": skill_id,
        "goal": goal,
        "constraints": constraints,
        "plan": plan_steps,
        "description": f"Proposed plan to {goal} with {len(plan_steps)} steps.",
    }


def apply(ctx: dict) -> dict:
    """Execute the skill: build the missing skill artifact."""
    skill_id = ctx.get("skill_id", "unknown")
    goal = ctx.get("goal", "build missing skill")
    dry_run = ctx.get("dry_run", False)

    if dry_run:
        return {
            "ok": True,
            "skill_id": skill_id,
            "dry_run": True,
            "message": f"Dry-run complete for '{skill_id}'. No side-effects produced.",
        }

    artifact_lines = [
        f"# Auto-generated skill stub: {skill_id}",
        f"# Goal: {goal}",
        "",
        "def propose(ctx): return {'ok': True}",
        "def apply(ctx): return {'ok': True}",
        "def test(ctx): return {'ok': True}",
    ]
    artifact_content = "\n".join(artifact_lines)

    artifacts_dir = ctx.get("artifacts_dir")
    written_path = None

    if artifacts_dir:
        target = artifacts_dir.rstrip("/").rstrip("\\") + "/" + skill_id + "_skill.py"
        try:
            with open(target, "w", encoding="utf-8") as fh:
                fh.write(artifact_content)
            written_path = target
        except OSError:
            return {
                "ok": False,
                "skill_id": skill_id,
                "error": f"Failed to write artifact to {target}",
            }

    return {
        "ok": True,
        "skill_id": skill_id,
        "goal": goal,
        "artifact_path": written_path,
        "artifact_size": len(artifact_content),
        "message": f"Skill '{skill_id}' built successfully.",
    }


def test(ctx: dict) -> dict:
    """Self-test: verify propose and apply behave correctly."""
    errors = []

    # --- test propose ---
    try:
        p = propose(ctx)
        if not isinstance(p, dict):
            errors.append("propose() did not return a dict")
        elif not p.get("ok"):
            errors.append("propose() returned ok=False")
    except Exception as exc:
        errors.append(f"propose() raised {type(exc).__name__}: {exc}")

    # --- test apply (dry_run) ---
    try:
        dry_ctx = dict(ctx, dry_run=True)
        a = apply(dry_ctx)
        if not isinstance(a, dict):
            errors.append("apply() did not return a dict")
        elif not a.get("ok"):
            errors.append("apply() returned ok=False")
        elif not a.get("dry_run"):
            errors.append("apply() did not honour dry_run flag")
    except Exception as exc:
        errors.append(f"apply() raised {type(exc).__name__}: {exc}")

    # --- test apply (real, with artifacts_dir if available) ---
    if ctx.get("artifacts_dir"):
        try:
            r = apply(ctx)
            if not isinstance(r, dict):
                errors.append("apply(real) did not return a dict")
            elif not r.get("ok"):
                errors.append(f"apply(real) returned ok=False: {r.get('error')}")
        except Exception as exc:
            errors.append(f"apply(real) raised {type(exc).__name__}: {exc}")

    return {
        "ok": len(errors) == 0,
        "errors": errors,
        "tests_run": 3 if ctx.get("artifacts_dir") else 2,
        "message": "All checks passed." if not errors else "; ".join(errors),
    }
